import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { activityFilterSchema } from "@/schemas/activity";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import { createTenant, issueInput, useTemporaryDatabase } from "$R/tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => { unregisterEventHandlers(); cleanup(); });

describe("move", () => {
  it("works end to end", async () => {
    const t = await createTenant("mv");
    const other = await createTenant("mvother");
    const target = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Target", slug: "target", key: "TGT", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
    const a1 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "searchable alpha", assigneeId: t.userIds.admin }));
    const a2 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "second" }));
    await issueService.createIssue(t.actors.member, issueInput(t.org.id, target.id, { title: "target one" }));
    const events: unknown[] = []; const others: string[] = [];
    const offs = [subscribe("issue.moved", (p) => { events.push(p); }),
      ...(["issue.created", "issue.updated", "issue.archived", "issue.status_changed", "issue.assigned"] as const).map((k) => subscribe(k, () => { others.push(k); }))];

    // same project: no-op
    const same = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a2.id, toProjectId: t.project.id });
    expect(same).toEqual(await issueRepo.findIssueById(t.org.id, a2.id));
    expect(events).toHaveLength(0);

    // viewer denied
    await expect(issueService.moveIssueToProject(t.actors.viewer, { orgId: t.org.id, issueId: a2.id, toProjectId: target.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    // cross-org project not found
    await expect(issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a2.id, toProjectId: other.project.id })).rejects.toThrow(/not found/);

    const moved = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a2.id, toProjectId: target.id });
    expect(moved.projectId).toBe(target.id);
    expect(moved.number).toBe(2);
    expect(moved).toEqual(await issueRepo.findIssueById(t.org.id, a2.id));
    expect(events).toEqual([expect.objectContaining({ issueId: a2.id, fromProjectId: t.project.id, toProjectId: target.id, fromNumber: 2, toNumber: 2, actorId: t.userIds.member, orgId: t.org.id })]);
    expect(others).toEqual([]);

    // retired number in source
    expect(await issueRepo.nextIssueNumber(t.org.id, t.project.id)).toBe(3);
    const a3 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "third" }));
    expect(a3.number).toBe(3);

    // move away and back
    const back = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a2.id, toProjectId: t.project.id });
    expect(back.number).toBe(4);
    expect(await issueRepo.nextIssueNumber(t.org.id, target.id)).toBe(3);

    // move a1 to target, untouched fields
    const m1 = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a1.id, toProjectId: target.id });
    expect({ ...m1, projectId: a1.projectId, number: a1.number, updatedAt: a1.updatedAt }).toEqual(a1);
    expect(m1.number).toBe(3);

    // audit
    const log = await activityRepo.listActivity(activityFilterSchema.parse({ orgId: t.org.id, action: ["issue.moved"], limit: 25 }));
    expect(log.items).toHaveLength(3);
